export function offenseTravel(f,move,a,b){const d=offenseVfxDescriptor(move);if(!d)return false;
 switch(d.pattern){
  case'strike':strikes(f,d,a,b,move);break;case'cleave':cuts(f,d,a,b);break;case'jaws':jaws(f,d,a,b);break;case'bind':coil(f,d,a,b);break;case'tongue':tongue(f,d,a,b);break;
  case'flame-stream':fire(f,d,a,b);break;case'waterjet':water(f,d,a,b);break;case'lightning':lightning(f,d,a,b);break;case'icebeam':iceRay(f,d,a,b);break;case'energybeam':energy(f,d,a,b);break;case'psybeam':psychicBeam(f,d,a,b);break;case'triad':triad(f,d,a,b);break;case'dragonstream':fire(f,{...d,colors:[0x4945b8,0x9976dd,0xcab2f1],width:d.width*.72,count:10},a,b);psychicBeam(f,{...d,colors:[0x6760b8,0xa391d2,0xc1b3df],count:5,width:d.width*.23},a,b);break;
  case'volley':volley(f,d,a,b,move);break;case'leaves':case'petals':leaves(f,d,a,b);break;case'drain':drain(f,d,a,b);break;case'roots':roots(f,d,a,b);break;
  case'cyclone':if(d.trajectory==='silver-scale-stream')silverScales(f,d,a,b);else cyclone(f,d,a,b);break;case'sound':ringsInFlight(f,d,a,b);particles(f,{...d,colors:[d.colors[0],d.colors[1],d.colors[1]]},b,basis(a,b).forward,'note',3,d.scale*.14,{additive:false,opacity:.68});break;
  case'wave':case'surge':wave(f,d,a,b);break;case'blizzard':blizzard(f,{...d,colors:[0x4fa9cc,0x9bd9ed,0xd6eef6]},a,b);break;case'cloud':cloud(f,d,a,b);break;case'sludge':cloud(f,{...d,count:8,scale:d.scale*.7},a,b);pathSprites(f,d,a,b,'water',7,{spread:d.spread||1,height:d.height||1,size:d.scale*.35,life:.9});break;
  case'scatter':scatter(f,d,a,b);break;case'spin':spin(f,d,a,b);break;case'drill':drill(f,d,a,b);break;case'grapple':grapple(f,d,a,b);break;case'boomerang':boomerang(f,d,a,b);break;case'wing':if(d.trajectory==='high-bounce-drop')bounceDrop(f,d,b);else wing(f,d,a,b);break;case'rockfall':stonePrison(f,d,b);break;case'bomb':thrownProp(f,d,a,b);break;
  case'dash':dash(f,d,a,b);break;case'bubbles':bubbles(f,d,a,b);break;case'stars':stars(f,d,a,b);break;case'rocks':rocks(f,d,a,b);break;case'fire-glyph':glyph(f,d,b);break;
  default:projectileAccent(f,d,a,b);break;
 }return true;
}

function dash(f,d,a,b){const {side,forward}=basis(a,b),s=d.scale,n=Math.min(5,d.echoes||3),elementShape=d.coreTexture==='bolt'?'bolt':d.coreTexture==='flame'?'flame':d.coreTexture==='water'?'water':d.coreTexture==='smoke'?'smoke':'slash';for(let i=0;i<n;i++){const t=(i+.5)/n,p=a.clone().lerp(b,t),m=sprite(f,elementShape,p,d.colors[i%3],[s*.9,s*1.2,1],.8,{opacity:.6,angle:angleOnScreen(f,forward)});animate(f,m,{delay:i*.035,from:p.clone().addScaledVector(side,Math.sin(i)*s*.12),to:p.clone().addScaledVector(forward,s*.45),scaleFrom:.75,scaleTo:1.15,opacityFrom:.75,opacityTo:0});}for(const sign of [-1,1])beam(f,a.clone().addScaledVector(side,sign*s*.3),b.clone().addScaledVector(side,sign*s*.3),d.colors[1],s*.32,.7,{shape:'streak',opacity:.85});if(d.trajectory==='ascending-waterfall')wave(f,d,a,b);else if(d.trajectory==='phoenix-dive')wing(f,{...d,coreTexture:'flame'},a,b);shock(f,b,d,.95);}
