function rocks(f,d,a,b){pathSprites(f,d,a,b,'rock',d.count,{spread:d.trajectory==='orbiting-relics'?2:1,height:d.height||2,curve:d.trajectory==='orbiting-relics'?'spiral':'arc',turns:d.turns||1,size:[d.scale*.45,d.scale*.4,1],life:1,stagger:.035});const {forward}=basis(a,b);particles(f,d,b,forward,'rock',7,d.scale*.25,{additive:false,opacity:.9});}
function glyph(f,d,p){const s=d.scale;sprite(f,'fire-glyph',p,d.colors[0],s*1.1,d.life,{opacity:.96,grow:.2});sprite(f,'fire-glyph',p,d.colors[2],s*.78,d.life*.9,{opacity:.88,grow:.3});light(f,p,d.colors[1],s*1.25,.9,.45);particles(f,d,p,new THREE.Vector3(0,0,1),'flame',12,[s*.2,s*.5,1]);}
