 if(d.pattern==='blizzard'){for(let i=0;i<n;i++){const a=i/n*TAU,p=g.clone().add(new THREE.Vector3(Math.cos(a)*r*.7,1.3+(i%4)*.65,Math.sin(a)*r*.7)),m=sprite(f,'ice',p,d.colors[i%3],[s*.2,s*.45,1],1.1,{opacity:.88,spin:1.8});animate(f,m,{delay:i*.015,from:p,to:p.clone().add(new THREE.Vector3(-Math.sin(a)*1.5,-1,Math.cos(a)*1.5)),curve:'orbit',radius:.8,turns:1.4,axis:UP,opacityFrom:.95,opacityTo:0});if(i%3===0)sprite(f,'plume',p,d.colors[1],s*.7,1.1,{opacity:.27,grow:.5});}return true;}
 if(d.pattern==='rockfall'){for(let i=0;i<Math.min(n,13);i++){const a=i/Math.min(n,13)*TAU,to=g.clone().add(new THREE.Vector3(Math.cos(a)*r*.65,.4,Math.sin(a)*r*.65)),from=to.clone().addScaledVector(UP,(d.height||5)+i%3*.5),m=sprite(f,'rock',from,d.colors[i%3],[s*.45,s*.5,1],1.1,{additive:false,opacity:.95,spin:.8});animate(f,m,{delay:i*.035,from,to,curve:'arc',height:.1,scaleFrom:.8,scaleTo:1.05,opacityFrom:1,opacityTo:.2});sprite(f,'smoke',to,d.colors[1],s*.55,1,{additive:false,opacity:.35,grow:.7});}shock(f,g,d,.8,.95);return true;}
 // The ground techniques have a true surface silhouette, not suspended generic
 // rings: branched fractures, a single chasm, or a mound that erupts upward.
 for(let i=0;i<Math.min(n,16);i++){const a=i/Math.min(n,16)*TAU,p=g.clone().add(new THREE.Vector3(Math.cos(a)*r*.55,.02,Math.sin(a)*r*.55)),fracture=sprite(f,'crack',p,d.colors[0],[r*1.5,r*.9,1],1.15,{billboard:false,additive:false,opacity:.9});if(fracture)fracture.rotation.set(-Math.PI/2,0,a);if(i%2===0){const m=sprite(f,'rock',p,d.colors[1],[s*.35,s*.5,1],1.05,{additive:false,opacity:.9});animate(f,m,{delay:i*.02,from:p,to:p.clone().addScaledVector(UP,d.pattern==='eruption'?(d.height||3):1.1),curve:'arc',height:1,scaleFrom:.2,scaleTo:1,opacityFrom:1,opacityTo:0});}if(i%3===0)sprite(f,'smoke',p,d.colors[1],s*.65,1.1,{additive:false,opacity:.36,grow:.8});}
