 if(/fire|flame|sun|phoenix|ember/.test(kind)){sprite(f,'plume',at,d.colors[0],[s*.9,s*1.3,1],.95,{opacity:.7,grow:.5});particles(f,d,at,dir,'flame',n,[s*.18,s*.42,1]);light(f,at,d.colors[2],s*.7,.6,.65);}
